    'faq_note' => 'Answers to common questions.',
    'faq_q1' => '<strong>What is TropaTT?</strong><br>A free apri-source self-hosted CRM, attività manager, and progetto management platform.',
    'faq_q10' => 'Who is the developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM or a attività manager?</strong><br>Both. A CRM for clients and counterparties, a attività manager for attività, plus progetto management, chat, calendario, and AI.',
    'faq_q3' => '<strong>Is it suitable for freelancers?</strong><br>Yes. There is no minimum team size. A single utente gets CRM, attività, an AI day plan, and chat without per-seat fees.',
    'faq_q4' => '<strong>Does it work on shared hosting?</strong><br>Yes. PHP 8.1+ and MySQL are enough. The browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits on utenti and attività?</strong><br>No. Unlimited utenti, attività, progetti, and clients. The only limitation is server capacity.',
    'faq_q6' => '<strong>Where is the dati stored?</strong><br>100% on your server. The system never syncs dati to the cloud.',
    'faq_q7' => '<strong>What AI tools are disponibile?</strong><br>20+ tools: idea exploration, day/settimana plans, summaries, checklists, risks, meeting preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API with an OpenAPI 3.1 spec generated from code.',
    'faq_q9' => '<strong>Can it be customized?</strong><br>Yes. PHP code, moduli, webhooks, API, workflow rules, custom fields, ruoli, and access rights.',
    'faq_title' => 'Frequently asked questions',
    'gantt_intro' => 'Gantt displays progetto attività on a timeline. It lets you plan deadlines, track dependencies, and monitor resource overload.',
